"""Additional, explicitly editorial encounters with the approved quotations."""
from html import escape
from quote_sources import quote_block

DIALOGUES = {
 'leto-gospodne-pamyat': [
  ('smysl-molitvy', 'У Шмелёва ребёнок постепенно учится понимать то, что сначала узнаёт по голосу, запаху и привычному движению взрослых. Мы тоже можем задержаться на словах молитвы. Что они значат для произносящего? Воспоминание о красивом обряде и внутренняя молитва связаны, но опыт одного человека не открывается другому полностью.'),
  ('mir-pered-molitvoy', 'Эта мысль возвращает праздничный рассказ к повседневным отношениям. С каким чувством человек входит в храм? Что происходит с тем, кого он оставил за дверью обиженным? Так церковный календарь становится для читателя ещё и вопросом о собственной жизни.')],
 'chistyy-ponedelnik-tayna': [
  ('sosredotochennaya-molitva', 'Наставление Евагрия помогает увидеть, что молитвенная жизнь требует внимания и труда. Но по нему нельзя разгадать героиню Бунина. Рассказчик видит её поступки извне, и мы вместе с ним остаёмся перед тайной другого человека.')],
 'sonya-slovo-i-prisutstvie': [
  ('ne-teriat-nadezhdy', 'Это слово о верности Богу среди испытаний. Рядом с романом оно помогает размышлять о надежде, которая не обещает мгновенного облегчения. Соня остаётся рядом с Раскольниковым, однако его признание и перемену ему предстоит пережить самому. Надежда на человека не даёт нам права требовать от него чувства по нашему расписанию.')],
 '8-unit-01': [
  ('nachat-s-molitvy', 'В житии молитва входит в действие героя и помогает понять, как сам текст объясняет его путь. Поэтому её важно читать в связи с конкретным эпизодом. Автобиографическое свидетельство другого автора может быть устроено иначе: общий религиозный словарь ещё не делает два произведения одинаковыми.')],
 '7-unit-04': [
  ('angely-i-svoboda', 'Василий Великий говорит здесь об Ангелах: это богословское высказывание о свободном пребывании в добре. Лермонтовский «Ангел» — поэтический текст со своим движением звука, памяти и тоски. Их встреча позволяет почувствовать общий круг вопросов, сохраняя различие церковного учения и художественного образа.'),
  ('blagodarnost-v-molitve', 'В стихотворении «Молитва» перемена выражена прежде всего интонацией и состоянием лирического героя. Святой Никодим говорит о более длительном труде: благодарить Бога и тогда, когда просьба не исполнилась. Такое соседство расширяет разговор о молитве за пределы одного пережитого мгновения.')],
 '8-unit-10': [
  ('serdechnaya-molitva', 'Воспоминание о церковной жизни может удерживать потерянный дом, голоса близких, привычный порядок дня. Слова «Добротолюбия» обращены к самой молитве. Они помогают читателю различить красоту воспоминания и духовную жизнь, которая не исчерпывается памятью о прошлом.')],
}

def additional_dialogue(key):
    return ''.join('<aside class="context-note"><h3>Ещё одна мысль для чтения</h3>' + quote_block(q) + '<p><strong>Комментарий мастерской.</strong> ' + escape(note) + '</p></aside>' for q, note in DIALOGUES.get(key, []))
